mapper.delete:
DELETE FROM ds_ck_query_history
WHERE tenant_id = #{tenantId} AND user_id = #{userId}
  AND connection_id = #{connectionId} AND raw_sql = #{rawSql}

mapper.select:
SELECT id, tenant_id, user_id, connection_id, connection_name, raw_sql, executed_at, created_at
FROM ds_ck_query_history
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND connection_id = #{connectionId}

  AND raw_sql LIKE CONCAT('%', #{keyword}, '%')

ORDER BY executed_at DESC, id DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM ds_ck_query_history
WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND connection_id = #{connectionId}
  AND id NOT IN (
    SELECT id FROM (
      SELECT id FROM ds_ck_query_history
      WHERE tenant_id = #{tenantId} AND user_id = #{userId} AND connection_id = #{connectionId}
      ORDER BY executed_at DESC, id DESC
      LIMIT #{keep}
    ) AS keep_ids
  )
